import{_ as a,o as i,c as s,a as t}from"./app.Dzj71sBz.js";const p=JSON.parse('{"title":"Hook Rust Benchmark Harness Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/HOOK_RUST_BENCHMARK_HARNESS_GUIDE.md","filePath":"guides/HOOK_RUST_BENCHMARK_HARNESS_GUIDE.md","lastUpdated":1771498270000}'),r={name:"guides/HOOK_RUST_BENCHMARK_HARNESS_GUIDE.md"};function o(n,e,c,d,l,u){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="hook-rust-benchmark-harness-guide" tabindex="-1">Hook Rust Benchmark Harness Guide <a class="header-anchor" href="#hook-rust-benchmark-harness-guide" aria-label="Permalink to &quot;Hook Rust Benchmark Harness Guide&quot;">​</a></h1><p>This guide documents the reproducible benchmark harness for <code>research-hook-rust-benchmarks</code>.</p><h2 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/benchmark-comprehensive.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="reproducibility-contract" tabindex="-1">Reproducibility Contract <a class="header-anchor" href="#reproducibility-contract" aria-label="Permalink to &quot;Reproducibility Contract&quot;">​</a></h2><p>The harness enforces stable benchmark conditions by default:</p><ul><li><code>LC_ALL=C</code></li><li><code>TZ=UTC</code></li><li>Fixed Hyperfine settings (<code>BENCH_WARMUP_RUNS</code>, <code>BENCH_MEASURE_RUNS</code>)</li><li>Explicit baseline/current output split per run</li><li>Run manifest with run-id, git SHA, and benchmark parameters</li></ul><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h2><p>Optional environment variables:</p><ul><li><code>THEGENT_BENCH_RESULTS_DIR</code> (default: <code>benchmarks/results</code>)</li><li><code>BENCH_RUN_ID</code> (default: UTC timestamp + git SHA)</li><li><code>BENCH_WARMUP_RUNS</code> (default: <code>3</code>)</li><li><code>BENCH_MEASURE_RUNS</code> (default: <code>20</code>)</li><li><code>BENCH_DRY_RUN=1</code> (plan-only mode)</li></ul><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>Each run writes:</p><ul><li><code>benchmarks/results/&lt;run-id&gt;/baseline/*.json</code></li><li><code>benchmarks/results/&lt;run-id&gt;/current/*.json</code></li><li><code>benchmarks/results/&lt;run-id&gt;/manifest.json</code></li><li><code>benchmarks/results/&lt;run-id&gt;/report.md</code></li><li><code>benchmarks/results/&lt;run-id&gt;/summary.json</code></li><li><code>benchmarks/results/latest</code> symlink</li></ul><p><code>report.md</code> and <code>summary.json</code> are generated by <code>scripts/benchmark-report.py</code> from Hyperfine JSON exports.</p>',14)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
